-- ============================================================
-- Sakila synthetic performance-test data (appended, skewed)
-- Generated: 2026-09-20T08:41:20.987Z
-- Order: widen ID columns, drop date triggers, load data, re-create triggers
-- IF THE IMPORT STOPS EARLY: run the CREATE TRIGGER statements at the bottom
-- of this file by hand, otherwise Sakila keeps running without its triggers.
-- ============================================================

USE sakila;

-- Step 1: widen ID columns that are too small for the new IDs.
-- The foreign keys on those columns are dropped first and added back right after.
ALTER TABLE `store` DROP FOREIGN KEY `fk_store_staff`;
ALTER TABLE `staff` DROP FOREIGN KEY `fk_staff_store`;
ALTER TABLE `customer` DROP FOREIGN KEY `fk_customer_store`;
ALTER TABLE `inventory` DROP FOREIGN KEY `fk_inventory_store`;
ALTER TABLE `rental` DROP FOREIGN KEY `fk_rental_staff`;
ALTER TABLE `payment` DROP FOREIGN KEY `fk_payment_staff`;
ALTER TABLE `staff` MODIFY staff_id SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT, MODIFY store_id SMALLINT UNSIGNED NOT NULL;
ALTER TABLE `store` MODIFY store_id SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT, MODIFY manager_staff_id SMALLINT UNSIGNED NOT NULL;
ALTER TABLE `customer` MODIFY store_id SMALLINT UNSIGNED NOT NULL;
ALTER TABLE `inventory` MODIFY store_id SMALLINT UNSIGNED NOT NULL;
ALTER TABLE `rental` MODIFY staff_id SMALLINT UNSIGNED NOT NULL;
ALTER TABLE `payment` MODIFY staff_id SMALLINT UNSIGNED NOT NULL, MODIFY payment_id INT UNSIGNED NOT NULL AUTO_INCREMENT;
ALTER TABLE `store` ADD CONSTRAINT `fk_store_staff` FOREIGN KEY (`manager_staff_id`) REFERENCES `staff` (`staff_id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `staff` ADD CONSTRAINT `fk_staff_store` FOREIGN KEY (`store_id`) REFERENCES `store` (`store_id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `customer` ADD CONSTRAINT `fk_customer_store` FOREIGN KEY (`store_id`) REFERENCES `store` (`store_id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `inventory` ADD CONSTRAINT `fk_inventory_store` FOREIGN KEY (`store_id`) REFERENCES `store` (`store_id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `rental` ADD CONSTRAINT `fk_rental_staff` FOREIGN KEY (`staff_id`) REFERENCES `staff` (`staff_id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `payment` ADD CONSTRAINT `fk_payment_staff` FOREIGN KEY (`staff_id`) REFERENCES `staff` (`staff_id`) ON DELETE RESTRICT ON UPDATE CASCADE;

-- Step 2: drop the triggers that overwrite create_date / rental_date / payment_date
DROP TRIGGER IF EXISTS customer_create_date;
DROP TRIGGER IF EXISTS payment_date;
DROP TRIGGER IF EXISTS rental_date;

-- Step 3: load the data
SET AUTOCOMMIT=0;



-- Point each new staff member at the store they manage
UPDATE staff SET store_id = staff_id + (0) WHERE staff_id BETWEEN 3 AND 1002;





























































































































































































































COMMIT;
SET AUTOCOMMIT=1;

-- Step 4: re-create the triggers we dropped
CREATE TRIGGER customer_create_date BEFORE INSERT ON customer FOR EACH ROW SET NEW.create_date = NOW();
CREATE TRIGGER payment_date BEFORE INSERT ON payment FOR EACH ROW SET NEW.payment_date = NOW();
CREATE TRIGGER rental_date BEFORE INSERT ON rental FOR EACH ROW SET NEW.rental_date = NOW();
